import {useLiveQuery} from 'dexie-react-hooks'; import {useState} from 'react'; import {db} from '../services/db'; import {saveProduct} from '../services/inventory'; import type {User} from '../types/models'; import {money} from '../utils/ids';
export default function Products({user}:{user:User}){const rows=useLiveQuery(()=>db.products.toArray(),[])||[]; const [f,setF]=useState<any>({arabic_name:'',barcode:'',purchase_price:0,selling_price:0,reorder_level:0,tax:0,active:true}); async function save(e:any){e.preventDefault(); await saveProduct(user.id,{...f,purchase_price:+f.purchase_price,selling_price:+f.selling_price,reorder_level:+f.reorder_level,tax:+f.tax,active:true}); setF({arabic_name:'',barcode:'',purchase_price:0,selling_price:0,reorder_level:0,tax:0,active:true})} return <section><h1>المنتجات</h1><form className="card formgrid" onSubmit={save}>{['arabic_name','english_name','generic_name','barcode','sku','category','manufacturer','purchase_price','selling_price','reorder_level'].map(k=><input key={k} value={f[k]||''} onChange={e=>setF({...f,[k]:e.target.value})} placeholder={k}/>) }<button>حفظ المنتج</button></form><div className="card"><table><thead><tr><th>الاسم</th><th>باركود</th><th>شراء</th><th>بيع</th><th>إعادة طلب</th></tr></thead><tbody>{rows.map(p=><tr key={p.id}><td>{p.arabic_name}</td><td>{p.barcode}</td><td>{money(p.purchase_price)}</td><td>{money(p.selling_price)}</td><td>{p.reorder_level}</td></tr>)}</tbody></table>{!rows.length&&<p className="empty">لا توجد منتجات بعد.</p>}</div></section>}
