import jsPDF from 'jspdf'; import autoTable from 'jspdf-autotable'; import { db } from './db';
export async function printInvoice(saleId:string){ const sale=await db.sales.get(saleId); if(!sale) throw new Error('الفاتورة غير موجودة'); const [items,settings]=await Promise.all([db.sale_items.where('sale_id').equals(saleId).toArray(),db.settings.get('settings')]); const products=await db.products.bulkGet(items.map(i=>i.product_id)); const doc=new jsPDF({orientation:'portrait',unit:'mm',format:settings?.default_paper==='A4'?'a4':[80,200]}); doc.setFontSize(14); doc.text(settings?.pharmacy_name||'ALSHIFAA',10,10); doc.setFontSize(9); doc.text(`Invoice: ${sale.invoice_no}`,10,18); autoTable(doc,{startY:24,head:[['Product','Qty','Price','Total']],body:items.map((it,idx)=>[products[idx]?.arabic_name||it.product_id,it.quantity,it.unit_price.toFixed(2),it.line_total.toFixed(2)])}); doc.text(`Total: ${sale.total.toFixed(2)} | Paid: ${sale.paid.toFixed(2)} | Remaining: ${sale.remaining.toFixed(2)}`,10,(doc as any).lastAutoTable.finalY+8); doc.save(`${sale.invoice_no}.pdf`); }
