import {NavLink,Route,Routes,Navigate} from 'react-router-dom'; import {useEffect,useState} from 'react'; import {currentUser,logout} from './services/auth'; import type {User} from './types/models'; import Dashboard from './pages/Dashboard'; import POS from './pages/POS'; import Products from './pages/Products'; import Inventory from './pages/Inventory'; import Purchases from './pages/Purchases'; import People from './pages/People'; import SimpleTablePage from './pages/SimpleTablePage'; import Reports from './pages/Reports'; import Settings from './pages/Settings'; import License from './pages/License'; import Backup from './pages/Backup'; import Login from './pages/Login'; import ErrorBoundary from './components/ErrorBoundary'; import OfflineBadge from './components/OfflineBadge';
const nav=[['/','الرئيسية'],['/pos','المبيعات'],['/products','المنتجات'],['/inventory','المخزون'],['/purchases','المشتريات'],['/customers','العملاء'],['/suppliers','الموردون'],['/returns','المرتجعات'],['/expenses','المصروفات'],['/payments','المدفوعات'],['/reports','التقارير'],['/users','المستخدمون'],['/settings','الإعدادات'],['/license','الترخيص'],['/backup','النسخ الاحتياطي']];
export default function App(){const [user,setUser]=useState<User|null|undefined>(); useEffect(()=>{currentUser().then(setUser)},[]); if(user===undefined)return <div className="center">جاري التحميل...</div>; if(!user)return <Login onLogin={setUser}/>; return <ErrorBoundary><div className="app"><aside><div className="brand">💊 ALSHIFAA</div>{nav.map(([to,label])=><NavLink key={to} to={to} end={to==='/'}>{label}</NavLink>)}<button className="ghost" onClick={()=>{logout();setUser(null)}}>تسجيل الخروج</button></aside><main><header><OfflineBadge/><span>{user.name} — {user.role}</span></header><Routes><Route path="/" element={<Dashboard/>}/><Route path="/pos" element={<POS user={user}/>}/><Route path="/products" element={<Products user={user}/>}/><Route path="/inventory" element={<Inventory user={user}/>}/><Route path="/purchases" element={<Purchases user={user}/>}/><Route path="/customers" element={<People type="customers" user={user}/>}/><Route path="/suppliers" element={<People type="suppliers" user={user}/>}/><Route path="/returns" element={<SimpleTablePage table="returns" title="المرتجعات"/>}/><Route path="/expenses" element={<SimpleTablePage table="expenses" title="المصروفات" creatable/>}/><Route path="/payments" element={<SimpleTablePage table="payments" title="المدفوعات"/>}/><Route path="/reports" element={<Reports/>}/><Route path="/users" element={<SimpleTablePage table="users" title="المستخدمون"/>}/><Route path="/settings" element={<Settings/>}/><Route path="/license" element={<License/>}/><Route path="/backup" element={<Backup user={user}/>}/><Route path="*" element={<Navigate to="/"/>}/></Routes></main></div></ErrorBoundary>}
