import {useState} from 'react'; import {login} from '../services/auth'; import type {User} from '../types/models';
export default function Login({onLogin}:{onLogin:(u:User)=>void}){const [username,setU]=useState('owner'),[password,setP]=useState('ChangeMe123!'),[err,setErr]=useState(''); async function submit(e:any){e.preventDefault(); setErr(''); try{onLogin(await login(username,password))}catch(x:any){setErr(x.message)}} return <div className="login"><form onSubmit={submit} className="card"><h1>ALSHIFAA Pharmacy ERP</h1><p>دخول محلي يعمل بدون إنترنت. المستخدم الافتراضي: owner / ChangeMe123! ويجب تغييره.</p><input value={username} onChange={e=>setU(e.target.value)} placeholder="اسم المستخدم أو البريد"/><input type="password" value={password} onChange={e=>setP(e.target.value)} placeholder="كلمة المرور"/><button>تسجيل الدخول</button>{err&&<div className="alert">{err}</div>}</form></div>}
