import {useLiveQuery} from 'dexie-react-hooks'; import {useState} from 'react'; import {db} from '../services/db'; import {postPurchase} from '../services/purchases'; import type {User} from '../types/models'; import {money} from '../utils/ids';
export default function Purchases({user}:{user:User}){const products=useLiveQuery(()=>db.products.toArray(),[])||[]; const purchases=useLiveQuery(()=>db.purchases.toArray(),[])||[]; const [f,setF]=useState<any>({invoice_no:'',paid:0,quantity:1}); async function save(e:any){e.preventDefault(); await postPurchase(user.id,undefined,f.invoice_no||`P-${Date.now()}`,+f.paid,[{product_id:f.product_id,batch_number:f.batch_number,quantity:+f.quantity,purchase_price:+f.purchase_price,selling_price:+f.selling_price,expiry_date:f.expiry_date,discount:+(f.discount||0),tax:+(f.tax||0)}]); setF({paid:0,quantity:1})} return <section><h1>المشتريات</h1><form className="card formgrid" onSubmit={save}><select onChange={e=>setF({...f,product_id:e.target.value})}><option>اختر منتج</option>{products.map(p=><option value={p.id}>{p.arabic_name}</option>)}</select>{['invoice_no','batch_number','quantity','purchase_price','selling_price','expiry_date','paid'].map(k=><input key={k} type={k.includes('date')?'date':k.includes('price')||k==='quantity'||k==='paid'?'number':'text'} value={f[k]||''} onChange={e=>setF({...f,[k]:e.target.value})} placeholder={k}/>) }<button>ترحيل الشراء</button></form><div className="card"><table><tbody>{purchases.map(p=><tr><td>{p.invoice_no}</td><td>{p.date}</td><td>{money(p.total)}</td><td>{money(p.remaining)}</td></tr>)}</tbody></table></div></section>}
