import {useState} from 'react'; import {getCachedLicense,licenseGate,validateLicense,clearLicense} from '../services/license';
export default function License(){const [endpoint,setEndpoint]=useState(localStorage.getItem('alshifaa_license_endpoint')||''),[key,setKey]=useState(''),[msg,setMsg]=useState(''); const l=getCachedLicense(), gate=licenseGate(); async function val(){try{localStorage.setItem('alshifaa_license_endpoint',endpoint); const r=await validateLicense(endpoint,key); setMsg(`تم التحقق: ${r.status}`)}catch(e:any){setMsg(e.message)}} return <section><h1>الترخيص</h1><div className="card"><p>{gate.message}</p><input value={endpoint} onChange={e=>setEndpoint(e.target.value)} placeholder="Supabase project URL"/><input value={key} onChange={e=>setKey(e.target.value)} placeholder="License key"/><button onClick={val}>تحقق وتفعيل</button><button className="ghost" onClick={()=>{clearLicense();location.reload()}}>مسح الترخيص المحلي</button>{msg&&<div className="alert">{msg}</div>}<pre>{JSON.stringify(l,null,2)}</pre></div></section>}
