import {useLiveQuery} from 'dexie-react-hooks'; import {useState} from 'react'; import {db} from '../services/db'; import type {User} from '../types/models'; import {now,uid,money} from '../utils/ids';
export default function People({type,user}:{type:'customers'|'suppliers';user:User}){const rows=useLiveQuery(()=>(db as any)[type].toArray(),[type])||[]; const [f,setF]=useState<any>({name:'',balance:0,credit_limit:0}); async function save(e:any){e.preventDefault(); await (db as any)[type].add({id:uid(type),pharmacy_id:user.pharmacy_id,created_at:now(),updated_at:now(),balance:0,...f}); setF({name:'',balance:0,credit_limit:0})} return <section><h1>{type==='customers'?'العملاء':'الموردون'}</h1><form className="card formgrid" onSubmit={save}>{['name','phone','address','email','company','notes','credit_limit'].map(k=><input key={k} value={f[k]||''} onChange={e=>setF({...f,[k]:e.target.value})} placeholder={k}/>) }<button>حفظ</button></form><div className="card"><table><thead><tr><th>الاسم</th><th>الهاتف</th><th>الرصيد</th></tr></thead><tbody>{rows.map((r:any)=><tr><td>{r.name}</td><td>{r.phone}</td><td>{money(r.balance)}</td></tr>)}</tbody></table></div></section>}
