import {useLiveQuery} from 'dexie-react-hooks'; import {db} from '../services/db'; import {useState,useEffect} from 'react'; import {now} from '../utils/ids';
export default function Settings(){const settings=useLiveQuery(()=>db.settings.get('settings'),[]); const [f,setF]=useState<any>({}); useEffect(()=>{if(settings)setF(settings)},[settings]); async function save(){await db.settings.update('settings',{...f,updated_at:now()})} return <section><h1>الإعدادات</h1><div className="card formgrid">{['pharmacy_name','address','phone','email','tax_number','currency_symbol','invoice_footer','default_paper','tax_rate','offline_grace_days'].map(k=><input value={f[k]||''} onChange={e=>setF({...f,[k]:e.target.value})} placeholder={k}/>) }<input type="file" accept="image/*" onChange={e=>{const file=e.target.files?.[0]; if(file){const r=new FileReader(); r.onload=()=>setF({...f,logo:r.result}); r.readAsDataURL(file)}}}/><button onClick={save}>حفظ الإعدادات</button></div></section>}
